order = self._store.get(self.ENTITY, self.PK, order_id)
    if order is None:
        return {}
    order_model = models.Order(**order)
    lines = self._store.select('OrderLine', [('order_id', 'eq', order_id)])
    customer = self._store.get('Customer', 'customer_id', order.get('customer_id'))
    order_with_lines = {
        'order': order_model,
        'customer': customer if customer else None,
        'lines': []
    }
    for line in lines:
        product = self._store.get('Product', 'product_id', line.get('product_id'))
        if product is not None:
            order_with_lines['lines'].append({
                'product': models.Product(**product),
                'quantity': line.get('quantity'),
                'unit_price': line.get('unit_price')
            })
    return order_with_lines
